def grandfather(apps, schema_editor):
    """Businesses already selling on the Market before vetting existed keep selling (as starter sellers)."""
    Listing = apps.get_model('core', 'MarketListing')
    Seller = apps.get_model('core', 'MarketSeller')
    Event = apps.get_model('core', 'MarketVettingEvent')
    from django.utils import timezone
    now = timezone.now()
    for bid in Listing.objects.values_list('business_id', flat=True).distinct():
        if Seller.objects.filter(business_id=bid).exists():
            continue
        b = apps.get_model('core', 'Business').objects.get(pk=bid)
        s = Seller.objects.create(business_id=bid, status='approved', level='starter', contact_name=b.owner_name or '',
                                  contact_phone=b.phone or '', town='', operating_since='', how_sell='', support_plan='',
                                  note='Approved automatically: already selling before TapTap started vetting sellers.',
                                  approved_at=now, reviewed_at=now, submitted_at=now)
        Event.objects.create(seller=s, action='approved', note='Grandfathered (listed before vetting existed)', created_at=now)



